"""Combine the spdx ids.

	Args:
		spdxA (str): spdx of the first license
		spdxB (str): spdx of the second license

	Returns:
		str: combined spdx
	"""
def mergeSPDX(spdxA: str, spdxB: str) -> str {
    if (len(spdxA) == 0) {
        return spdxB;
    }
    if (len(spdxB) == 0) {
        return spdxA;
    }
    return (spdxA + "+" + spdxB);
}

"""Returns local coordinate in a global region"""
def global2local(gobal_coord: Any, start: Any, end: Any, strand: Any) -> object {
    if (strand == 1) {
        return (gobal_coord - start);
    } else {
        return (end - gobal_coord);
    }
}

